@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=982  cases=30
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-116
  @fn seedItems(h, takes, srcLen)  @ 132-137
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 139-148

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 152-160
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 163-172
  @case 'focusState before any render returns both bits false'  [harness]  @ 175-182
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 188-201
  @case 'with no live instance, new take and unpooled duplicate mint a parked slot and select it'  [harness]  @ 205-227
  @case 'take properties renames the slot the tracker is on, not the bound take'  [harness]  @ 233-251
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 257-290
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 294-318
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 324-354
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 358-379
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 383-396
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 400-423
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 430-447
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 451-474
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 478-501
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 505-540
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 544-560
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 567-594
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 598-622
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 629-650
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 656-674
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 678-696
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 700-722
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 726-750
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 756-811
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 819-848
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 854-897
  @case 'empty grid shows the single no-takes message'  [harness]  @ 903-917
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 924-956
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 960-980

